use thermopack_rs::{Phase, SaftVrMie};

#[test]
fn test_saft_vrmie_pure_co2_states() {
    let eos = SaftVrMie::new(&["CO2"]).expect("failed to load CO2");
    assert_eq!(eos.num_components(), 1);

    // Point: T = 250.0 K, rho = 50.0 mol/m^3 (vapor)
    let prep = eos.prepare(250.0, &[1.0]).unwrap();
    let terms = prep.helmholtz_terms(50.0).unwrap();
    assert!(
        (terms.a_hs - 2.9279418014865172e-03).abs() < 1e-12,
        "a_hs diff: {}",
        (terms.a_hs - 2.9279418014865172e-03).abs()
    );
    assert!(
        (terms.a1 - -1.6329341430342525e+00).abs() < 1e-10,
        "a1 diff: {}",
        (terms.a1 - -1.6329341430342525e+00).abs()
    );
    assert!(
        (terms.a2 - -7.1498405669104528e+01).abs() < 1e-8,
        "a2 diff: {}",
        (terms.a2 - -7.1498405669104528e+01).abs()
    );
    assert!(
        (terms.a3 - -1.7426931006995510e+03).abs() < 1e-6,
        "a3 diff: {}",
        (terms.a3 - -1.7426931006995510e+03).abs()
    );
    let jet = prep.pressure_and_derivatives(50.0).unwrap();
    println!(
        "CO2 T=250 rho=50: d = {}, eta = {}, zeta_bar = {}, P_jet = {}, a_chain = {}, a_res = {}",
        prep.d()[0],
        prep.packing_fraction(50.0),
        prep.dispersion_packing_fraction(50.0),
        jet.pressure,
        terms.a_chain,
        terms.a_res
    );
    assert!(
        (jet.pressure - 1.0314379586043739e+05).abs() < 1.0314379586043739e+02,
        "P diff: {}",
        (jet.pressure - 1.0314379586043739e+05).abs()
    );
    let st = prep.state(50.0).unwrap();
    assert!(
        (st.ln_phi[0] - -7.5355607922518858e-03).abs() < 1e-5,
        "lnphi diff: {}",
        (st.ln_phi[0] - -7.5355607922518858e-03).abs()
    );

    // Point: T = 300.0 K, rho = 5000.0 mol/m^3 (subcritical dense gas)
    let prep = eos.prepare(300.0, &[1.0]).unwrap();
    let terms = prep.helmholtz_terms(5000.0).unwrap();
    assert!(
        (terms.a_hs - 3.1946016075735162e-01).abs() < 1e-12,
        "a_hs diff: {}",
        (terms.a_hs - 3.1946016075735162e-01).abs()
    );
    assert!(
        (terms.a1 - -1.7318039593034604e+02).abs() < 1e-10,
        "a1 diff: {}",
        (terms.a1 - -1.7318039593034604e+02).abs()
    );
    assert!(
        (terms.a2 - -4.5160020488158734e+03).abs() < 1e-8,
        "a2 diff: {}",
        (terms.a2 - -4.5160020488158734e+03).abs()
    );
    assert!(
        (terms.a3 - -3.0650382641946751e+05).abs() < 1e-6,
        "a3 diff: {}",
        (terms.a3 - -3.0650382641946751e+05).abs()
    );
    let jet = prep.pressure_and_derivatives(5000.0).unwrap();
    assert!(
        (jet.pressure - 6.5704472064612703e+06).abs() < 6.5704472064612701e+03,
        "P diff: {}",
        (jet.pressure - 6.5704472064612703e+06).abs()
    );
    let st = prep.state(5000.0).unwrap();
    assert!(
        (st.ln_phi[0] - -3.4878591645801371e-01).abs() < 1e-5,
        "lnphi diff: {}",
        (st.ln_phi[0] - -3.4878591645801371e-01).abs()
    );

    // Point: T = 350.0 K, rho = 15000.0 mol/m^3 (supercritical dense fluid)
    let prep = eos.prepare(350.0, &[1.0]).unwrap();
    let terms = prep.helmholtz_terms(15000.0).unwrap();
    assert!(
        (terms.a_hs - 1.1822473052941322e+00).abs() < 1e-12,
        "a_hs diff: {}",
        (terms.a_hs - 1.1822473052941322e+00).abs()
    );
    assert!(
        (terms.a1 - -5.6834745816045086e+02).abs() < 1e-10,
        "a1 diff: {}",
        (terms.a1 - -5.6834745816045086e+02).abs()
    );
    assert!(
        (terms.a2 - -6.0525779633463026e+03).abs() < 1e-8,
        "a2 diff: {}",
        (terms.a2 - -6.0525779633463026e+03).abs()
    );
    assert!(
        (terms.a3 - -2.5272483606788941e+05).abs() < 1e-6,
        "a3 diff: {}",
        (terms.a3 - -2.5272483606788941e+05).abs()
    );
    let jet = prep.pressure_and_derivatives(15000.0).unwrap();
    assert!(
        (jet.pressure - 2.3993221842738960e+07).abs() < 2.3993221842738960e+04,
        "P diff: {}",
        (jet.pressure - 2.3993221842738960e+07).abs()
    );
    let st = prep.state(15000.0).unwrap();
    assert!(
        (st.ln_phi[0] - -7.0353018711851778e-01).abs() < 1e-5,
        "lnphi diff: {}",
        (st.ln_phi[0] - -7.0353018711851778e-01).abs()
    );
}

#[test]
fn test_saft_vrmie_pure_co2_volume_and_saturation() {
    let eos = SaftVrMie::new(&["CO2"]).expect("failed to load CO2");
    let prep = eos.prepare(280.0, &[1.0]).unwrap();
    let p_target = 2.0e6; // 20 bar
    let vv = prep.volume(p_target, Phase::Vapor).unwrap();
    let jet_v = prep.pressure_and_derivatives(1.0 / vv).unwrap();
    assert!((jet_v.pressure - p_target).abs() < 1e-2);
    let vl = prep.volume(p_target, Phase::Liquid).unwrap();
    let jet_l = prep.pressure_and_derivatives(1.0 / vl).unwrap();
    assert!((jet_l.pressure - p_target).abs() < 1e-2);
    assert!(vl < vv);

    // Saturation pressure at 280 K: reference P_sat = 4.141998e+06 Pa
    let sat = prep.saturation_pressure(280.0).unwrap();
    assert!(
        (sat.pressure - 4.14199760e+06).abs() / 4.14199760e+06 < 1e-3,
        "sat P diff: {}",
        (sat.pressure - 4.14199760e+06).abs()
    );
    assert!((sat.liquid_volume - 4.85834503e-05).abs() / 4.85834503e-05 < 1e-2);
    assert!((sat.vapor_volume - 3.88138676e-04).abs() / 3.88138676e-04 < 1e-2);
}

