#[test]
fn test_saft_vrmie_binary_co2_c1() {
    let eos = SaftVrMie::new(&["CO2", "C1"]).expect("failed to load CO2,C1");
    assert_eq!(eos.num_components(), 2);
    assert_eq!(eos.get_kij(0, 1), 0.0);
    assert_eq!(eos.get_lij(0, 1), 0.0);

    let prep = eos.prepare(280.0, &[0.4, 0.6]).unwrap();
    let _terms = prep.helmholtz_terms(5000.0).unwrap();
    let jet = prep.pressure_and_derivatives(5000.0).unwrap();
    assert!((jet.pressure - 8.1241801122312928e+06).abs() < 1e-3 * 8.1241801122312928e+06);
    let st = prep.state(5000.0).unwrap();
    assert!((st.ln_phi[0] - -4.9836376670786747e-01).abs() < 1e-4);
    assert!((st.ln_phi[1] - -1.3314126363683471e-01).abs() < 1e-4);
}

